import{M as r,bK as n,ar as t,x as s,aG as a,L as i}from"./index-DWGrBUt2.js";const o="/assets/baihaba-line-C9VuNXVq.jpg",e={class:"chapter-content"},d={class:"section-media section-media--map"},p=["href"],h=["src"],b={__name:"Day2-布尔津-白哈巴",setup(g){return(c,l)=>(i(),r("div",e,[l[1]||(l[1]=n('<h2 id="今日主题">抵达白哈巴，再去高处看喀纳斯</h2><section class="day-opening" aria-label="今日旅行建议"><p class="day-opening__eyebrow">主选 · 08:00 起床 · 观鱼台</p><p class="day-opening__lead">10 月 4 日，从布尔津驶向白哈巴，预估 2.5—3 小时的车程后，先在村里放下行李。车停在在云端民宿或新村停车场附近的允许停车处，争取 12:00 入住在云端民宿。12:30 离开民宿，乘村内 2 号线到白哈巴游客中心，再换乘去喀纳斯。下午登观鱼台，把湖与山尽收眼底，晚上乘 20:00 末班车回白哈巴。</p><div class="day-opening__notes"><p><strong>把时间留给</strong>早餐退房后约 08:40 发车，途中休息与进村接驳另留余量；午餐提前备好，12:00 入住后吃简餐。三湾放在明天上午。</p><p><strong>出发前记住</strong>12:30 是从民宿出发时间；白哈巴 ⇄ 喀纳斯双向末班均为 20:00（用户 2026-09-29 当地补充）；白哈巴去喀纳斯坐右侧，喀纳斯去白哈巴坐左侧，沿途赏景。去程衔接与观鱼台专线另行确认。备选为 10:00 起床、约 14:00 到白哈巴，下午留村。</p></div></section><h2 id="关键时间轴">当天时间表 · 主选方案</h2>',3)),l[2]||(l[2]=t("div",{class:"table-scroll table-scroll--wide",tabindex:"0",role:"region","aria-label":"Day 2 主选时间轴"},[t("table",null,[t("thead",null,[t("tr",null,[t("th",{scope:"col"},"时间"),t("th",{scope:"col"},"安排"),t("th",{scope:"col"},"留意事项")])]),t("tbody",null,[t("tr",null,[t("th",{scope:"row"},[t("strong",null,"08:00")]),t("td",{"data-th":"安排"},"起床、洗漱、早餐、退房装车"),t("td",{"data-th":"留意事项"},"早餐与路餐提前准备，驾驶员吃完早餐再开车。")]),t("tr",null,[t("th",{scope:"row"},[t("strong",null,"约 08:40")]),t("td",{"data-th":"安排"},[t("strong",null,"从布尔津出发，直接前往白哈巴")]),t("td",{"data-th":"留意事项"},"走 S232／219 国道铁热克提方向直达线；预计驾驶 2.5—3 小时，累计约 2 小时之前完整停车至少 20 min，检查、候车和民宿接驳另计；12:00 为条件入住目标。")]),t("tr",null,[t("th",{scope:"row"},"约 11:30—12:00"),t("td",{"data-th":"安排"},"抵白哈巴，将车停在民宿或新村停车场附近"),t("td",{"data-th":"留意事项"},"争取 11:30 前后停车，按实际停车点给搬行李与到民宿留约 30 min；若 12:00 才到停车场，入住和午餐须顺延，不能仍按 12:30 离民宿，重新核下午窗口。社会车辆准入与民宿接送提前确认。")]),t("tr",null,[t("th",{scope:"row"},[t("strong",null,"12:00—12:30")]),t("td",{"data-th":"安排"},[t("strong",null,"入住在云端民宿、放行李、简餐")]),t("td",{"data-th":"留意事项"},"12:00 提前入住须请民宿确认；不能交房时先寄存行李，午餐打包。")]),t("tr",null,[t("th",{scope:"row"},[t("strong",null,"12:30")]),t("td",{"data-th":"安排"},[t("strong",null,"从民宿出发，乘村内 2 号线到白哈巴游客中心")]),t("td",{"data-th":"留意事项"},"先核最近上车站、候车时间和运营方向，按实际班次接上喀纳斯方向区间车。")]),t("tr",null,[t("th",{scope:"row"},"抵游客中心后"),t("td",{"data-th":"安排"},"换乘前往喀纳斯（导览图标喀纳斯 3 路）"),t("td",{"data-th":"留意事项"},"白哈巴 → 喀纳斯坐右侧赏景；单程暂按约 75 min 估算，去程衔接按当天班次；回程末班 20:00。")]),t("tr",null,[t("th",{scope:"row"},"下午"),t("td",{"data-th":"安排"},[t("strong",null,"换乘观鱼台专线，游观鱼台")]),t("td",{"data-th":"留意事项"},"为专线往返、排队与 1,068 级台阶留时间；建议留约 2.5—3 小时整体窗口，按返程末班倒推下山返回。")]),t("tr",null,[t("th",{scope:"row"},"19:30 前（至少提前 30 min）"),t("td",{"data-th":"安排"},"回喀纳斯换乘中心，候车返回白哈巴"),t("td",{"data-th":"留意事项"},"候乘 20:00 白哈巴方向末班；观鱼台下山专线末班另行确认，给下山与换乘留足时间。")]),t("tr",null,[t("th",{scope:"row"},[t("strong",null,"20:00 末班车")]),t("td",{"data-th":"安排"},[t("strong",null,"喀纳斯 → 白哈巴")]),t("td",{"data-th":"留意事项"},"白天喀纳斯 → 白哈巴坐左侧赏景；本班已过日落，按夜间返村准备，约 75 min 车程估算约 21:15 抵白哈巴游客中心，随后接已确认的村内公交或民宿接驳。")]),t("tr",null,[t("th",{scope:"row"},"返村后"),t("td",{"data-th":"安排"},"民宿热饭、洗漱休息，住白哈巴"),t("td",{"data-th":"留意事项"},"确认明日去三湾的早间班次及能在 15:45 抵白哈巴的回程。")])])])],-1)),l[3]||(l[3]=n('<h2 id="全程账">路程、导航与住宿</h2><ul><li><strong>主选导航：</strong>布尔津柒朵轻居酒店（86.877406,47.702818）→ S232／219 国道 → 铁热克提方向 → 在云端民宿或新村停车场附近允许停车处。既有白哈巴村停车场坐标（86.777679,48.692622）只作参考，不等同于已核实的新村停车点；最终定位向民宿确认。不再默认绕贾登峪。</li><li><strong>直达线：</strong>沿用 2026-09-06 记录约 140.8 km / 2 h 37 min；本次按用户预估 2.5—3 小时驾驶排程。国庆车流、检查、休息与村内接驳另留余量。</li><li><strong>住宿：</strong>在云端民宿，双湖路 11 号，POI B0KRDHMBXU，86.781171,48.683209；2 间大床房 × ¥880 = <strong>¥1,760，10-04 已订</strong>。12:00 提前入住待民宿确认。</li><li><strong>停车与接驳：</strong>主选将车停在民宿或新村停车场附近，确认可过夜及 10-05 退房后继续停车；旧停车场到民宿的 1.184 km / 16 min 不能套用到新停车点。10-05 早上先退房，车近把大件行李放进车里，车远寄存在民宿、游完三湾再取，再到新村停车场乘村内 2 路；车辆主选停至 10-05 下午返村取车，备选停至 10-06 早上。</li><li><strong>天文参考：</strong>布尔津 10-04 日出约 08:15、日落约 19:47；山地实际见光与天色受地形天气影响。</li></ul><h2 id="路线与停车">路线与停车</h2><h3 id="铁贾公路通道静态路线">绕贾登峪路线：仅在官方要求时重排行程</h3><p>原布尔津 → 贾登峪 → 铁热克提 → 白哈巴为 222.0 km / 4 h 06 min 历史路线，本次不再作为主选。若当天指定检查通道要求绕行，须重新计算到村与喀纳斯游览时间，不能继续套用 12:00 入住和 12:30 出发的安排。</p><h3 id="直达备选线">主选直达线：布尔津 → 铁热克提 → 白哈巴</h3><p>按用户 2026-09-29 调整，将原直达备选线升为主选：S232 北疆海岸大桥 → 岔冲段 → 219 国道塔铁段 → 铁扎段／铁白段 → 白哈巴村停车场，约 140.8 km / 2 h 37 min。出发前核对景区指定检查入口、社会车辆准入与边境证件；既有地图记录不等于当日放行。若直达线无法通行，服从官方路线并重排下午，不压缩休息赶车。</p><h2 id="边防证与票务前置">进山前办好边防证与票务</h2><div class="alert-banner is-warning"><strong>边防证须提前申请并获批，支付宝可办理</strong><p>2026-09-30 重新核读<a href="https://s.nia.gov.cn/mps/bszy/dzbjtxz/blzy/202604/t20260414_1001.html" target="_blank" rel="noreferrer">国家移民管理局服务指南及常见问题</a>：年满 16 周岁的内地居民，可通过支付宝“移民局 12367”小程序免费申请有效期三个月以内的电子边境管理区通行证（俗称边防证），APP、微信小程序也可办理。网上受理后 <strong>3 个工作日内决定是否批准</strong>；已提交、受理中或待审核均不等于已获批。</p><p><strong>这次旅行的办理时间：</strong>10-02 出发、10-04 进入白哈巴。提前 1—2 周办理是本书的准备建议；今天 9 月 30 日已临近国庆，未办者立即申请，并拨打 <a href="tel:12367">12367</a> 或向受理机构核实假期受理及现场办理安排。工作日不等于自然日，不能承诺线上申请赶得上 10-04。<strong>入山前必须拿到覆盖本次行程的已签发通行证</strong>，不依赖游客中心临时受理。</p></div><h3 id="支付宝边防证办理流程">支付宝“移民局 12367”办理流程</h3><p>以下适用于年满 16 周岁、单独申领三个月以内电子证的内地居民；四人符合条件时各自用本人身份申请。入口类别参考<a href="https://wlt.xizang.gov.cn/xccx/lytg/202604/t20260415_535038.html" target="_blank" rel="noreferrer">政府发布的操作说明</a>，具体按钮和字段按当前小程序提示。</p><ol><li><strong>找入口并实名：</strong>打开支付宝，搜索“移民局 12367”，进入国家移民管理局官方小程序，完成本人注册、登录和实名认证；需要人脸核验时按提示操作。</li><li><strong>选择业务：</strong>进入“中国公民服务”，找到“电子边境管理区通行证”相关申领服务，阅读办理须知后开始申请。</li><li><strong>准备并填写资料：</strong>备好本人有效居民身份证、符合要求的免冠照片及本人邮箱；按页面要求填写个人信息、联系方式和申请资料。事由按本次行程选“旅游”；受理机构或照片采集方式按平台提示确认。</li><li><strong>核对目的地与有效期：</strong><a href="https://s.nia.gov.cn/mps/bszy/dzbjtxz/blzy/202604/W020260414621567380501.png" target="_blank" rel="noreferrer">官方申请表示例</a>按地区列出前往地，本次选择“新疆维吾尔自治区 → 阿勒泰地区”，覆盖白哈巴所在地区；页面另要求具体行程时，如实填写哈巴河县白哈巴，不能只凭“喀纳斯”景区名判断。有效期覆盖 10-04/05；若采用续住备选，也覆盖 10-06 出山日。其他需证边境路段、具体起止日期及签发范围按平台和受理机构确认。</li><li><strong>提交后查结果：</strong>留好申请记录，回小程序查看审核结果，并留意补正通知和本人邮箱；材料退回时按要求补齐。“提交成功”或受理截图只能用于查进度，不能作为通行证。</li><li><strong>获批后备证：</strong>下载已签发电子证或从指定邮箱收取，核对姓名、证件号、前往区域和有效期；离线保存完整电子证，建议另备打印件。检查时与本人有效身份证件同时出示，电子证在有效期内可多次往返。</li></ol><div class="callout is-note"><strong>哪些情况要现场办理</strong><p>港澳台居民、华侨、外国人，偕行不满 16 周岁子女或申请一年有效期的内地居民，须到县级以上公安机关出入境管理机构或指定派出所申请；网上申请有困难的内地居民也可走现场渠道。未满 16 周岁子女作为偕行人，需有效身份证件（未办身份证可用户口簿）及监护关系证明，不能照搬成人线上流程。</p><p>现场申请备齐申请表、免冠照片、有效身份证件及适用的其他材料。材料齐全且符合法定形式可当场签发；需进一步调查的，受理后 10 个工作日内决定。去之前先确认可受理地点、假期值班与材料要求；取得边境证件后，白哈巴当日身份准入、门票和车辆许可仍分别核实。未获批或证件覆盖不符时，取消受影响行程并处理住宿退改。</p></div><div class="callout is-note"><strong>票价作预算参考，放票与准入另行确认</strong><p>原 2026-09-05 记录为白哈巴门票 ¥30/人、区间车 ¥45/人，喀纳斯一进 ¥230、二进 ¥270、全域票 ¥375；这些只用于预算对照，实际日期、票种、景区交通覆盖和退改看官方购票页。通过景区公众号或原行网核实放票窗口；本次未取得“每天 10:00、提前 7 天”的当期依据，不将其写作固定抢票时间。</p><p>社会车辆能否经铁热克提到村停车场，须另行确认准入预约、检查入口和是否仍需景交费；地图可导航不代表放行。班车、门票与车辆准入分别确认，不能把其中一项当作其余项目也已完成。</p></div><div class="callout is-note"><strong>进山前，连着确认好五段衔接</strong><p>① 直达线指定入口与社会车辆准入；② 12:00 交房或寄存行李及停车场接送；③ 12:30 离民宿后的村内 2 号线和白喀去程；④ 观鱼台专线、20:00 回程及约 21:15 后的返村接驳；⑤ 10-05 能在 15:45 抵白哈巴的实际回程。票种须覆盖 10-04/05 从白哈巴往返的两个日期和景交，不仅凭“一进/二进”名称判断。</p><p>20:00 末班已由当地信息补充，其余环节不能因此视为已确认。第二晚白哈巴房态房价与布尔津退改未落实前，续住只是待落实分支；提前发现条件不成立就缩短喀纳斯游览或留村，并重排 D3，续住房间须落实后才能计入安排。</p></div><h2 id="白哈巴内部交通">白哈巴内部交通与喀纳斯 3 路</h2><p>导览图由用户提供，用于理解铁热克提、白哈巴、喀纳斯三端与村内站点关系。图片未标适用日期，按图理解线路关系与估算车程。用户 2026-09-29 补充当地信息：<strong>喀纳斯 ⇄ 白哈巴双向末班均为 20:00</strong>；面向车辆前进方向，<strong>喀纳斯去白哈巴坐左侧，白哈巴去喀纳斯坐右侧</strong>，白天班次沿途赏景，20:00 末班按夜间返村准备。村内 2 号线及观鱼台专线的时刻另行确认；12:30 是离开民宿的计划时间。</p>',17)),t("figure",d,[t("a",{href:s(o),target:"_blank",rel:"noreferrer","aria-label":"打开白哈巴交通导览图原图"},[t("img",{src:s(o),alt:"白哈巴交通导览图，标示铁热克提、白哈巴与喀纳斯游客服务中心之间的公交线路，以及老村、新村、观景平台、步行和骑马路线",width:"1440",height:"1080",loading:"lazy",decoding:"async"},null,8,h)],8,p),l[0]||(l[0]=t("figcaption",null,[t("strong",null,"白哈巴交通导览图"),t("span",null,"点击查看原图；图示只用于理解线路关系，实际运营以 2026 国庆现场公告为准。"),t("small",null,[t("button",{type:"button",class:"credit-link","data-action":"open-credit","data-asset":"baihaba-line"},"来源与使用说明")])],-1))]),l[4]||(l[4]=t("div",{class:"table-scroll table-scroll--wide",tabindex:"0",role:"region","aria-label":"白哈巴交通线路摘要"},[t("table",null,[t("thead",null,[t("tr",null,[t("th",{scope:"col"},"线路"),t("th",{scope:"col"},"导览图标注"),t("th",{scope:"col"},"本次用途")])]),t("tbody",null,[t("tr",null,[t("th",{scope:"row"},"白哈巴 1 路"),t("td",{"data-th":"导览图标注"},"铁热克提游客中心 ↔ 白哈巴游客中心；往返 68 km / 约 160 min"),t("td",{"data-th":"本次用途"},"社会车辆不能进村时的替代接驳；启用后重新核算 D2 下午观鱼台窗口")]),t("tr",null,[t("th",{scope:"row"},"白哈巴 2 路"),t("td",{"data-th":"导览图标注"},"白哈巴游客中心 ↔ 新村停车场；往返 7.4 km / 约 45 min"),t("td",{"data-th":"本次用途"},"本次主选村内接驳：12:30 从民宿出发，到就近站点乘 2 号线前往游客中心")]),t("tr",null,[t("th",{scope:"row"},"喀纳斯 3 路"),t("td",{"data-th":"导览图标注"},"喀纳斯游客中心 ↔ 白哈巴游客中心；往返 62 km / 约 150 min"),t("td",{"data-th":"本次用途"},"双向末班 20:00；喀纳斯 → 白哈巴坐左侧，反向坐右侧。D2 及 D3 续住备选乘 20:00 末班；D3 主选仍乘能在 15:45 抵村的较早班次")])])])],-1)),l[5]||(l[5]=n('<h2 id="风险与降级">遇到变化时</h2><ul><li><strong>到村延误：</strong>重新核算入住、村内 2 号线、白喀区间车与观鱼台专线；下午窗口不足时，优先采用下方“不改住宿的减量线”；只有续住与退改已落实，才切换两晚白哈巴完整备选。</li><li><strong>班次未落实：</strong>白喀双向末班按当地补充为 20:00；去程具体班次、上车点及观鱼台下山专线另行确认，19:30 前回喀纳斯换乘中心候车。</li><li><strong>观鱼台关闭或排队过长：</strong>缩短停留并提前下山返回，按已确认末班返白哈巴；不挤占回程候车时间。</li><li><strong>改住两晚：</strong>切换备选前确认 10-05 白哈巴续住与鸿宇福瑞退改，次日改 09:00 从白哈巴去奎屯。</li></ul><h2 id="今日吃什么">今日吃什么</h2>',3)),l[6]||(l[6]=t("div",{class:"table-scroll table-scroll--fit",tabindex:"0",role:"region","aria-label":"Day2 餐饮安排"},[t("table",null,[t("thead",null,[t("tr",null,[t("th",{scope:"col"},"餐次"),t("th",{scope:"col"},"店铺 / 地点"),t("th",{scope:"col"},"评分 / 人均 / 营业"),t("th",{scope:"col"},"说明")])]),t("tbody",null,[t("tr",null,[t("th",{scope:"row"},"早餐"),t("td",{"data-th":"店铺"},[t("strong",null,"马依莱牛肉面"),a("（和湖路 11 号，位于柒朵与鸿宇福瑞之间，距柒朵步行约 400 m）；打包兜底：六点半早餐（神湖路店，距柒朵约 400 m）")]),t("td",{"data-th":"评分 / 人均 / 营业"},"4.5 / 约 ¥32 / 24 小时；3.7 / 约 ¥25 / 06:30—15:00"),t("td",{"data-th":"说明"},[a("牛肉面＋茶蛋顶饱且 24 小时营业，主选约 08:40 发车前吃完或打包。用户指定的布尔津县一壶奶茶馆营业时间为 "),t("strong",null,"10:00—22:00"),a("（2026-09-29 回填），赶不上本日出发，改列 D3 回城后的奶茶简餐")])]),t("tr",null,[t("th",{scope:"row"},"午餐"),t("td",{"data-th":"店铺"},"D1 既有休息或用餐时段备好的路餐"),t("td",{"data-th":"评分 / 人均 / 营业"},"— / — / —"),t("td",{"data-th":"说明"},"馕、卤蛋、水果、能量棒、热饮，12:00—12:30 入住时吃；不依赖白哈巴村现场采购")]),t("tr",null,[t("th",{scope:"row"},"晚餐"),t("td",{"data-th":"店铺"},"在云端民宿简餐（提前请民宿备汤面/粥）；备选 野有餐廳（白哈巴村双湖路 56 号，距民宿步行约 720 m）"),t("td",{"data-th":"评分 / 人均 / 营业"},"— / — / —；4.5 / 约 ¥94 / 09:00—23:30"),t("td",{"data-th":"说明"},"当日末班车返村后吃，优先民宿包餐，不为找饭再走动；2026-09-29 高德 MCP 周边搜已在村内取到独立餐厅数据（见美食指南“白哈巴村内餐厅”），民宿不供餐时可按表点一份热菜，夜间步行带手电并结伴")])])])],-1)),l[7]||(l[7]=n('<ul><li><strong>早餐安排：</strong>乘员上车后吃，驾驶员停车吃完再驾驶；两家店都排队就用已备早餐，驾驶员吃完再上路；早餐延误影响接驳时重算观鱼台窗口，不空腹赶车。</li><li><strong>路餐补齐：</strong>D1 休息或用餐时把路餐备好，晚间只清点数量，按全天车行准备，白哈巴与喀纳斯都不作采购依赖。</li></ul><p><strong>想把时间留给哪里：</strong>主选把观鱼台与三湾分成两天，白喀车内接驳合计约 5 h，白哈巴白天留给村游的时间很少；下方备选少一次往返约 150 min，代价是第二晚住宿退改及 D4 596.6 km 长途。20:00 末班时白哈巴已过约 19:47 日落，回程车窗已看不到白天的村落景色；若村落体验最重要，可优先选下方不改住宿的减量线；只有还想同日完成三湾与观鱼台，才在进山前连着三天确认续住备选。</p><h3 id="不改住宿的减量线">不改住宿的减量线：留村半日，放弃补赶观鱼台</h3><p>若到村延误、观鱼台关闭、接驳不合适或司机需要休息，<strong>D2 下午留村，仍住已订在云端；D3 只选三湾，不补赶观鱼台</strong>。确认较早回程后，仍以 15:45 抵白哈巴、最迟 16:30 前取车出村为目标，10-05 住已订鸿宇福瑞，D4 10:00 从布尔津去奎屯。这样少一次白喀往返约 150 min，又不新增第二晚白哈巴住宿和 D4 长途；代价是放弃观鱼台。票种改按实际单日游览核对，已购票退改另行确认，不承诺一定退款。</p><p>若 D3 也没有能衔接取车出山的早回班次，就不进喀纳斯，改白哈巴村游后提早出山。该减量线仍要求白哈巴准入、接驳和出山道路成立；证件与道路条件仍须满足。</p><h3 id="车停铁热克提的衔接">车停铁热克提时，D2 与 D3 一起重排</h3><p>仅社会车辆不能进村而人员准入成立时，先核实铁热克提的合法停车、白哈巴 1 路双向班次、票务及民宿接行李。导览图的 1 路往返约 160 min，只能暂估单程约 80 min，候车和装车另计。<strong>D3 的 15:45 抵白哈巴不等于已回到车旁</strong>：还要取行李、从白哈巴游客中心乘 1 路回铁热克提再取车，不能继续套村内 16:30 发车或白哈巴出发的 140.4 km。</p><p>入山前按“铁热克提至布尔津实时驾驶＋餐休＋取车＋1 路接驳＋白喀回程”倒推 D3 结束游览，并确认各段末班和排队余量；无法安全衔接就取消 D3 喀纳斯、提早离村，或在入山前取消受影响行程。这些接驳提前约妥，D3 返村后才能顺利取车出山。</p><h2 id="今日可选项">备选方案：10:00 起床，下午留白哈巴</h2><p><strong>三天一起切换：</strong>10-04 10:00 起床，从布尔津出发，约 14:00 到白哈巴并入住；下午游村。10-05 早上去喀纳斯，将三湾与观鱼台安排在同一天，乘 20:00 末班车回白哈巴，晚上继续住村里。10-06 09:00 从白哈巴出发前往奎屯。</p><p>10-04 建议 10:00—10:45 吃早餐、退房装车，约 10:45 出发，按 2.5—3 小时驾驶及短休争取 14:00 到村。此分支当天不进喀纳斯；10-05 续住房价、房态与布尔津酒店退改待核，不能把 10-04 已订房价当作第二晚已订。下午可这样安排：</p><ol><li><strong>午餐后先休息 30—45 min：</strong>入住、热饭和热水都办妥，再出门。若仍需等房，先约定行李寄存；主选打包午餐不必照搬到留村日。</li><li><strong>老村慢走 45—60 min：</strong>沿开放主街看木屋、围栏与河谷，挑一个角度拍四人合影。观察建筑、生活用品和树木变化，比赶多个招牌更容易记住这个村子；不进入未开放的院子。</li><li><strong>热茶与一个故事 30—45 min：</strong>提前问民宿能否安排本地主人介绍过冬、木屋生活或音乐；谈好总价、时长和内容，有公开演奏再听一小段。没有安排就坐下喝茶，不把普通住户当作随时接待的“家访点”。</li><li><strong>日落前的一处开放观景点：</strong>留 30—40 min 看村落与河谷的光线，步行返回和吃晚饭的时间一起预留。前面只选一至两项，坐着看风景也是完整体验。</li></ol><p><strong>骑马只作替换：</strong>若有人明确想骑，用一次 30—45 min 的正规短线替换文化停留，问清经营方、牵引人员、头盔、路线、总价与保险；不涉河、不上陡坡。没有合适组织就改散步，不再在赛湖安排第二次骑乘。</p><p>文化背景见<a href="https://www.hbh.gov.cn/xwdt/002012/20240718/a8ee0a6b-c42f-4a6d-a605-9d49a0f21042.html" target="_blank" rel="noreferrer">哈巴河县政府 2024 年白哈巴报道</a>；这只能说明地方体验的方向，不能证明在云端已经提供演出或家访。拍人、进入院落和录音先征得同意，不拍边境设施。全书约定时间均为北京时间，与接待方确认时也说清这一点。</p><h3 id="白哈巴一小时怎么过">留村的一小时，慢慢看什么</h3><p>在云端位于南村。去老村前，请民宿说明开放入口与接送方式，给从住处到主街留出时间。到公共主街后，先用 15 min 看木屋的材料、屋顶和围栏，再用 20—25 min 走到当天允许的开阔处看河谷；四个人各选一个喜欢的细节，最后留 10 min 合影与休息。遇到居民先打招呼，拍人或进院前征得同意。</p><p>若想多了解一点，可请主人讲冬天如何取暖、当地早餐吃什么，先确认对方是否有时间；这是交谈建议，不是已包含的导览项目。天冷或下雨就把这段换成一杯热茶与一顿提前问好的家常菜。主选去观鱼台时不再叠加这一小时。</p><h2 id="出发前核验">出发前确认</h2><ul><li><label class="task task-live"><input type="checkbox" data-check-index="0"> <span>主选 08:00 起床、约 08:40 布尔津直达白哈巴，按 2.5—3 小时驾驶及检查休息准备</span></label></li><li><label class="task task-live"><input type="checkbox" data-check-index="1"> <span>直达线检查入口、铁热克提方向通行及社会车辆停车准入已核对</span></label></li><li><label class="task task-live"><input type="checkbox" data-check-index="2"> <span>10-04 在云端 ¥1,760 已订；12:00 入住或寄存行李、停车场接送已确认</span></label></li><li><label class="task task-live"><input type="checkbox" data-check-index="3"> <span>12:00—12:30 简餐已备，12:30 出发乘村内 2 号线的上车站与班次已确认</span></label></li><li><label class="task task-live"><input type="checkbox" data-check-index="4"> <span>已记下白喀双向末班 20:00、19:30 前候车；去程班次、观鱼台专线及返程候车点已确认</span></label></li><li><label class="task task-live"><input type="checkbox" data-check-index="5"> <span>主选双日进入喀纳斯的票种、有效期与景区交通覆盖已核；备选按单日游览确认</span></label></li><li><label class="task task-live"><input type="checkbox" data-check-index="6"> <span>备选 10-05 白哈巴续住、布尔津退改和 10-06 09:00 出发已核对</span></label></li><li><label class="task task-live"><input type="checkbox" data-check-index="7"> <span>四人适用的边境通行证均已获批，前往区域与有效期覆盖本次白哈巴行程；已离线保存完整电子证或打印件，带好有效身份证件并完成官方预约</span></label></li></ul>',19))]))}};export{b as default};
